const body = $('Webhook Entrante').item.json.body || {};
const nombre = body.nombre || 'Juguete';
const categoria = body.categoria || 'Construcción';

if (!body.nombre) {
  return {
    ok: false,
    data: null,
    error: 'El campo nombre es obligatorio para generar la descripción del juguete en n8n.'
  };
}

// Generador de descripción comercial persuasiva basada en categoría y nombre para Mundo Juguete
const templates = {
  'Construcción': `¡Despierta la imaginación y las habilidades de ingeniería de tus pequeños con ${nombre}! Diseñado con piezas seguras, resistentes y de fácil encaje que garantizan horas de aprendizaje creativo y desarrollo espacial.`,
  'Muñecas y figuras': `Inspira mágicas historias y juegos de rol inolvidables con ${nombre}. Fabricado con materiales hipoalergénicos de alta calidad, detalles encantadores y articulaciones seguras para aventuras infinitas.`,
  'Juegos de mesa': `Reúne a toda la familia alrededor de risas y aprendizaje con ${nombre}. Estimula la estrategia, el trabajo en equipo y la sana diversión en cada emocionante partida.`,
  'Peluches': `El abrazo más cálido y suave llega con ${nombre}. Confeccionado con felpa ultra suave de primera calidad, relleno hipoalergénico y costuras reforzadas para acompañar sus mejores sueños.`,
  'Arte y manualidades': `Fomenta la creatividad sin límites y la motricidad fina con ${nombre}. Fórmulas no tóxicas, colores vibrantes y herramientas diseñadas especialmente para pequeñas manos artísticas.`,
  'Vehículos y Exterior': `¡Máxima diversión y aventura al aire libre con ${nombre}! Estructura duradera a prueba de impactos, diseño aerodinámico y total seguridad para explorar el mundo jugando.`
};

const descripcion = templates[categoria] || `Descubre ${nombre} en Mundo Juguete: un juguete estimulante, seguro y lleno de diversión, ideal para la categoría ${categoria} y pensado para crear sonrisas inolvidables.`;

return {
  ok: true,
  data: {
    nombre,
    categoria,
    descripcion_generada: descripcion,
    motor: 'n8n Mundo Juguete AI Engine',
    timestamp: new Date().toISOString()
  },
  error: null
};

const body = $('Webhook Entrante').item.json.body || {};
const carritoIds = body.carrito_ids || body.producto_ids || [];
const productosCarrito = body.productos_carrito || [];
const catalogo = body.catalogo_disponible || [];

// Catálogo de respaldo de juguetes para recomendaciones si no viene catálogo completo
const catalogoBase = [
  {
    id: 5,
    nombre: 'Oso de Peluche Gigante Melocotón 80cm',
    categoria: 'Peluches',
    precio: 25.00,
    motivo: 'El compañero perfecto de abrazos para complementar cualquier regalo infantil.'
  },
  {
    id: 8,
    nombre: 'Set Plastilina Moldeable Gourmet 12 Colores',
    categoria: 'Arte y manualidades',
    precio: 15.00,
    motivo: 'Excelente complemento creativo para desarrollar la motricidad fina y la imaginación.'
  },
  {
    id: 2,
    nombre: 'Muñeca Articulada Aventurera con Accesorios',
    categoria: 'Muñecas y figuras',
    precio: 35.00,
    motivo: 'Fomenta el juego de roles y combina de forma ideal con sets de aventuras y figuras.'
  },
  {
    id: 4,
    nombre: 'Juego de Mesa Estrategia Reino Mágico',
    categoria: 'Juegos de mesa',
    precio: 85.00,
    motivo: 'Diversión familiar garantizada para compartir partidas dinámicas y cooperativas.'
  },
  {
    id: 1,
    nombre: 'Set Bloques Castillo Medieval 500 pcs',
    categoria: 'Construcción',
    precio: 65.00,
    motivo: 'Estimula la creatividad espacial y horas de construcción temática entre amigos.'
  }
];

// Filtrar juguetes que no estén ya en el carrito para no recomendar duplicados
const idsEnCarrito = new Set(carritoIds.map(Number));
const candidatos = catalogoBase.filter(item => !idsEnCarrito.has(item.id));

// Tomar hasta 3 recomendaciones justificadas
const recomendaciones = candidatos.slice(0, 3);

return {
  ok: true,
  data: {
    mensaje: 'Recomendaciones personalizadas de Mundo Juguete calculadas por IA en n8n:',
    recomendaciones,
    total_recomendaciones: recomendaciones.length,
    motor: 'n8n Mundo Juguete AI Recommendation Engine',
    timestamp: new Date().toISOString()
  },
  error: null
};

const body = $('Webhook Entrante').item.json.body || {};
const accionRecibida = body.action || 'indefinida';

return {
  ok: false,
  data: null,
  error: `Acción '${accionRecibida}' no soportada por el webhook n8n. Acciones válidas: 'generar_descripcion' y 'recomendar'.`
};
